package com.arjunren.loan;
import com.arjunren.loan.domain.*; import com.arjunren.loan.dto.Dtos.*; import com.arjunren.loan.entity.AppUser; import com.arjunren.loan.exception.DomainException; import com.arjunren.loan.repository.*; import com.arjunren.loan.service.LoanService; import java.math.BigDecimal; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.ActiveProfiles; import static org.assertj.core.api.Assertions.*;
@SpringBootTest@ActiveProfiles("test")class LoanServiceTests{@Autowired UserRepository users;@Autowired LoanApplicationRepository loans;@Autowired RepaymentRepository repayments;@Autowired LoanService service;AppUser customer,other,officer;@BeforeEach void setup(){repayments.deleteAll();loans.deleteAll();users.deleteAll();customer=users.save(new AppUser("customer@example.com","x","Customer",Role.CUSTOMER));other=users.save(new AppUser("other@example.com","x","Other",Role.CUSTOMER));officer=users.save(new AppUser("officer@example.com","x","Officer",Role.LOAN_OFFICER));}@Test void fullLifecycleAndRepayment(){var l=service.apply(new ApplyRequest(new BigDecimal("1200"),12,"Equipment"),customer);service.approve(l.id(),new BigDecimal("10"),officer);service.disburse(l.id(),officer);var payment=service.repay(l.id(),new BigDecimal("1320"),customer);assertThat(payment.amount()).isEqualByComparingTo("1320.00");assertThat(service.get(l.id(),customer).status()).isEqualTo(LoanStatus.PAID);}@Test void ownershipIsEnforced(){var l=service.apply(new ApplyRequest(new BigDecimal("1000"),12,"Study"),customer);assertThatThrownBy(()->service.get(l.id(),other)).isInstanceOf(DomainException.class);}@Test void onlyPendingLoansCanBeApproved(){var l=service.apply(new ApplyRequest(new BigDecimal("1000"),12,"Study"),customer);service.reject(l.id(),"Risk",officer);assertThatThrownBy(()->service.approve(l.id(),BigDecimal.TEN,officer)).isInstanceOf(DomainException.class);}@Test void overpaymentIsRejected(){var l=service.apply(new ApplyRequest(new BigDecimal("1200"),12,"Equipment"),customer);service.approve(l.id(),BigDecimal.ZERO,officer);service.disburse(l.id(),officer);assertThatThrownBy(()->service.repay(l.id(),new BigDecimal("1201"),customer)).isInstanceOf(DomainException.class).hasMessageContaining("exceeds");}}

